#pragma once
#include <algorithm>
#include <cctype>
#include <string>

// Returns true if a and b are anagrams of each other: same multiset of
// letters, ignoring case and ignoring any non-alphabetic characters.
inline bool is_anagram(const std::string& a, const std::string& b) {
    std::string sa, sb;
    for (char c : a) {
        if (std::isalpha((unsigned char)c)) {
            sa += (char)std::tolower((unsigned char)c);
        }
    }
    for (char c : b) {
        if (std::isalpha((unsigned char)c)) {
            sb += (char)std::tolower((unsigned char)c);
        }
    }
    if (sa.size() != sb.size()) {
        return false;
    }
    std::sort(sa.begin(), sa.end());
    std::sort(sb.begin(), sb.end());
    return sa == sb;
}

